layer.css:
@import url("https://fonts.googleapis.com/css?family=Material+Icons");
[data-ryt="pitch"] { color: rgb(20, 92, 164); background-color: color-mix(in srgb, var(--ryt-accent) 5%, transparent); border-left: 3px solid color-mix(in srgb, var(--ryt-accent) 70%, transparent); border-radius: 0px; font-family: -apple-system, BlinkMacSystemFont, "segoe ui", Roboto, "helvetica neue", Arial, "noto sans", sans-serif, "apple color emoji", "segoe ui emoji", "segoe ui symbol", "noto color emoji"; font-size: 16px; font-weight: 400; font-style: normal; line-height: 1.5; letter-spacing: normal; text-transform: none; text-decoration-style: solid; text-decoration-color: rgb(20, 92, 164); text-decoration-thickness: auto; text-underline-offset: auto; text-shadow: color-mix(in srgb, var(--ryt-text) 0%, transparent) 1px 1px 1px; padding-top: 10px; padding-right: 20px; padding-bottom: 10px; padding-left: 20px; transition: all; border-top: none; border-right: none; border-bottom: none }
article[data-ryt="rec-card"] { border-bottom: 1px solid rgba(128, 128, 128, 0.12); border-radius: 0px; transition: all; border-top: none; border-right: none; border-left: none }
[data-ryt="credit"] a, [data-ryt="review"] a, [data-ryt="bio"] a { color: var(--ryt-accent); border-radius: 0px; font-weight: 400; font-style: normal; letter-spacing: normal; text-transform: none; text-decoration-style: solid; text-decoration-color: var(--ryt-accent); text-decoration-thickness: auto; text-underline-offset: auto; text-shadow: color-mix(in srgb, var(--ryt-text) 0%, transparent) 1px 1px 1px; transition: all }
[data-ryt="brand"] { color: var(--ryt-text); border-radius: 0px; font-family: -apple-system, BlinkMacSystemFont, "segoe ui", Roboto, "helvetica neue", Arial, "noto sans", sans-serif, "apple color emoji", "segoe ui emoji", "segoe ui symbol", "noto color emoji"; font-size: 30px; font-weight: 400; font-style: normal; line-height: 1.4; letter-spacing: normal; text-transform: none; text-decoration-style: solid; text-decoration-color: var(--ryt-text); text-decoration-thickness: auto; text-underline-offset: auto; text-shadow: color-mix(in srgb, var(--ryt-text) 0%, transparent) 1px 1px 1px; transition: all }
[data-ryt="nav"] a { color: var(--ryt-text); border-right: 2px solid rgba(0, 0, 0, 0); border-radius: 0px; font-family: -apple-system, BlinkMacSystemFont, "segoe ui", Roboto, "helvetica neue", Arial, "noto sans", sans-serif, "apple color emoji", "segoe ui emoji", "segoe ui symbol", "noto color emoji"; font-size: 20px; font-weight: 400; font-style: normal; line-height: 1.5; letter-spacing: normal; text-transform: none; text-decoration-style: solid; text-decoration-color: var(--ryt-text); text-decoration-thickness: auto; text-underline-offset: auto; text-shadow: color-mix(in srgb, var(--ryt-text) 0%, transparent) 1px 1px 1px; padding-top: 8px; padding-right: 28px; padding-bottom: 8px; padding-left: 30px; transition: all; border-top: none; border-bottom: none; border-left: none }
[data-ryt="review"] { color: var(--ryt-text); font-family: -apple-system, BlinkMacSystemFont, "segoe ui", Roboto, "helvetica neue", Arial, "noto sans", sans-serif, "apple color emoji", "segoe ui emoji", "segoe ui symbol", "noto color emoji"; font-size: 16px; font-weight: 400; font-style: normal; line-height: 1.5; letter-spacing: normal; text-transform: none; text-decoration-style: solid; text-decoration-color: var(--ryt-text); text-decoration-thickness: auto; text-underline-offset: auto; text-shadow: color-mix(in srgb, var(--ryt-text) 0%, transparent) 1px 1px 1px; transition: all }
[data-ryt="credit"], [data-ryt="eyebrow"] { color: var(--ryt-text); font-family: -apple-system, BlinkMacSystemFont, "segoe ui", Roboto, "helvetica neue", Arial, "noto sans", sans-serif, "apple color emoji", "segoe ui emoji", "segoe ui symbol", "noto color emoji"; font-size: 16px; font-weight: 400; font-style: normal; line-height: 1.5; letter-spacing: normal; text-transform: none; text-decoration-style: solid; text-decoration-color: var(--ryt-text); text-decoration-thickness: auto; text-underline-offset: auto; text-shadow: color-mix(in srgb, var(--ryt-text) 0%, transparent) 1px 1px 1px; transition: all }
[data-ryt="rec-card"] [data-ryt="title"] a { color: var(--ryt-accent); border-radius: 0px; font-family: -apple-system, BlinkMacSystemFont, "segoe ui", Roboto, "helvetica neue", Arial, "noto sans", sans-serif, "apple color emoji", "segoe ui emoji", "segoe ui symbol", "noto color emoji"; font-weight: 400; font-style: normal; letter-spacing: normal; text-transform: none; text-decoration-style: solid; text-decoration-color: var(--ryt-accent); text-decoration-thickness: auto; text-underline-offset: auto; text-shadow: color-mix(in srgb, var(--ryt-text) 0%, transparent) 1px 1px 1px; transition: all }
[data-ryt="rec-card"] [data-ryt="title"] { color: var(--ryt-text); border-radius: 0px; font-family: -apple-system, BlinkMacSystemFont, "segoe ui", Roboto, "helvetica neue", Arial, "noto sans", sans-serif, "apple color emoji", "segoe ui emoji", "segoe ui symbol", "noto color emoji"; font-size: 30px; font-weight: 500; font-style: normal; line-height: 1.5; letter-spacing: normal; text-transform: none; text-decoration-style: solid; text-decoration-color: var(--ryt-text); text-decoration-thickness: auto; text-underline-offset: auto; text-shadow: color-mix(in srgb, var(--ryt-text) 0%, transparent) 1px 1px 1px; transition: all }
[data-ryt="rec-card"] [data-ryt="title"]:hover { text-decoration-line: underline; text-decoration-thickness: initial; text-decoration-style: initial; text-decoration-color: initial; color: rgb(20, 92, 164) }
[data-ryt="rec-card"] [data-ryt="title"] a:hover { color: rgb(0, 86, 179); text-decoration-line: underline; text-decoration-thickness: initial; text-decoration-style: initial; text-decoration-color: initial; color: rgb(20, 92, 164); text-decoration-line: none; text-decoration-thickness: initial; text-decoration-style: initial; text-decoration-color: initial }
[data-ryt="credit"]:hover, [data-ryt="eyebrow"]:hover { color: rgb(20, 92, 164) }
[data-ryt="review"]:hover { color: rgb(20, 92, 164) }
[data-ryt="nav"] a:hover { color: rgb(0, 86, 179); text-decoration-line: underline; text-decoration-thickness: initial; text-decoration-style: initial; text-decoration-color: initial; color: rgb(20, 92, 164); text-decoration-line: none; text-decoration-thickness: initial; text-decoration-style: initial; text-decoration-color: initial; border-right-width: 2px; border-right-style: solid; border-right-color: color-mix(in srgb, var(--ryt-accent) 60%, transparent); background-image: initial; background-color: color-mix(in srgb, var(--ryt-accent) 2%, transparent); color: rgb(9, 41, 73) }
[data-ryt="credit"] a:hover, [data-ryt="review"] a:hover, [data-ryt="bio"] a:hover { color: rgb(0, 86, 179); text-decoration-line: underline; text-decoration-thickness: initial; text-decoration-style: initial; text-decoration-color: initial; color: rgb(20, 92, 164) }
article[data-ryt="rec-card"]:hover { color: rgb(20, 92, 164) }
